#include <cstdio>
#include <map>
#include <algorithm>
using namespace std;

typedef pair<int,int> P;
P mt[200];

int dp[1000][201];

int main() {
    int n, m;

    while (scanf("%d", &n), n) {
        for (int i = 0; i < n; i++) {
            int a, b;
            scanf("%d %d", &a, &b);
            mt[i] = P(a, b);
        }

        scanf("%d", &m);
        for (int i = 0; i < m; i++) {
            int a, b;
            scanf("%d %d", &a, &b);
            mt[n + i] = P(a, b);
        }

        sort(mt, mt + m + n);
        fill(&dp[0][0], &dp[0][0] + sizeof(dp) / sizeof(int), 1000);

        int ans = 0;
        for (int i = 0; i < m + n; i++) {
            int h = mt[i].first;
            int r = mt[i].second;
            dp[h][1] = min(dp[h][1], r);
            // Optimized nested loop
            for (int j = 0; j < h; j++) {
                for (int k = 1; k <= m + n; k++) {
                    if (r > dp[j][k - 1]) {
                        dp[h][k] = min(dp[h][k], r);
                    }
                }
            }
        }

        for (int i = 0; i < 1000; i++) {
            for (int j = 0; j <= m + n; j++) {
                if (dp[i][j] != 1000) {
                    ans = max(ans, j);
                }
            }
        }

        printf("%d\n", ans);
    }
}

